pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor funds the contract and a caller attempts withdrawAll
    function testFuzz_property(uint256 depositAmount, address caller) public {
        // keep depositAmount in a reasonable wide range but non-zero
        depositAmount = bound(depositAmount, 1, 1 ether);
        // caller should not be the owner to distinguish correct behavior; fuzz may still try owner
        vm.assume(caller != address(this)); // ensure caller isn't this test contract (owner)

        // fund the caller so they can send Ether to the contract
        vm.deal(caller, depositAmount);

        // Have caller send Ether to contract via fallback by making a plain call with value
        vm.prank(caller);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // After funding, contract balance equals depositAmount
        assert(address(c).balance == depositAmount);

        // Now attempt to call withdrawAll as the fuzzed caller
        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): If caller is NOT the owner, withdrawAll must NOT succeed in draining the contract.
        // We observe this by checking: when caller != owner, either the call reverted (ok == false) OR contract balance remains unchanged.
        // The reference contract enforces onlyOwner, so for all inputs it holds that non-owners cannot drain the balance.
        // The mutant removing the require allows some non-owner callers to succeed, violating this property for some fuzzed inputs.
        address owner = c.owner();
        if (caller != owner) {
            // Reference: non-owner cannot drain, so either call reverted (ok==false) or balance still equals depositAmount
            assertTrue(!ok || address(c).balance == depositAmount);
        } else {
            // If caller is owner, withdrawAll should succeed and contract balance becomes 0
            // (we do not assert here to keep the single assertion rule for the non-owner case)
            assertTrue(true);
        }
    }
}

