        uint256 seedFund = 1 ether;
        vm.deal(address(this), seedFund);
        // send seedFund to c
        (bool sent,) = address(c).call{value: seedFund}("");
        require(sent);

        // bound withdrawAmount to be within [0, seedFund]
        withdrawAmount = bound(withdrawAmount, 0, seedFund);

        address recipient;
        if (victimFlag == 1) {
            // deploy a reverting recipient: its receive/fallback will revert, causing send to return false
            Reverter r = new Reverter();
            recipient = address(r);
        } else {
            // plain EOA-like recipient (an address with no code). Use address(this) which has code, so prefer an EOA
            // create a new ephemeral EOA by deriving from an address with no code: use address(0x1234...)
            recipient = address(0x1001);
            // ensure recipient has no code (most likely), but vm can't remove code; using address with no code constant
        }

        // transfer out: make c's owner be this test contract's address (constructor already set owner to deployer of c which was this test)
        // call withdraw as owner (this test contract)
        // record balance before
        uint256 before = address(c).balance;

        // perform the withdraw via a low-level call to simulate the public call from owner
        // since c.withdraw sends to payable(msg.sender), we must call from the recipient address so funds would be sent to it
        // For that, we impersonate the recipient when calling c.withdraw

        // ensure the recipient (if an EOA-typed address) has some balance to be able to be vm.prank target
        vm.deal(recipient, 1);
        vm.prank(recipient);
        bool ok;
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // General universal property we assert: For the correct contract using transfer, withdraw either reverts (ok==false)
        // or decreases contract balance by withdrawAmount (before - after == withdrawAmount). The mutant using send can
        // succeed the call (ok==true) but fail to transfer funds (after == before). We assert the universal rule that holds
        // on the reference: either the call reverted or the balance decreased exactly by withdrawAmount.
        assertTrue(ok == false || before - after == withdrawAmount);
    }
