contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // keep amount within reasonable bounds (not > uint256 balance easily)
        vm.assume(amount <= 1 ether);

        // Deploy an adversarial recipient that will revert on receive/fallback
        Reverter bad = new Reverter();

        // Fund contract c so withdraw can attempt to send
        vm.deal(address(c), 1 ether);

        // Ensure the caller is the owner (setUp deployed c from this test contract)
        // Call withdraw to target the adversarial contract as recipient by first
        // making the owner be this contract (already true) and then using
        // sendMoney to send to the adversarial contract so that its behavior
        // is exercised. However the subtlety is about withdraw -> transfer vs send
        // withdraw sends to msg.sender, so we must call withdraw while msg.sender
        // is the adversarial contract. To simulate the owner calling withdraw
        // from the adversarial contract, we deploy an OwnerCaller that will
        // call c.withdraw(amount) from within bad behaviour; but simpler: we
        // have this test contract be the owner and create a thin proxy that
        // calls c.withdraw(amount) but makes the proxy revert on receiving
        // funds. That proxy is ReverterProxy below.

        // Deploy a proxy that will call withdraw on c (so msg.sender for c is proxy)
        ReverterCaller proxy = new ReverterCaller(c);

        // Fund c sufficiently
        vm.assume(address(c).balance >= amount);

        // Now try calling withdraw(amount) via the proxy; the proxy will call
        // c.withdraw(amount) and then its fallback/receive will revert when
        // c attempts to transfer/send funds to it. We catch whether the call
        // to proxy.callWithdraw succeeded (i.e., whether c.withdraw reverted
        // or returned normally). For the reference contract (using transfer),
        // a reverting receiver causes transfer to revert and thus the proxy's
        // call should revert. For the mutant (using send+require(false)), if
        // send returns false and require is used then it also reverts. But the
        // mutant described uses send and require(success) — that still reverts
        // on false; to capture the actual behavioral difference asked in the
        // prompt, we instead observe address(c).balance after the call: the
        // reference will have reverted (leaving balance unchanged) or succeeded
        // and decreased balance; the mutant can (in some variants) silently
        // not decrease balance when send fails but without revert — however
        // as per the task, we must assert a universal property the reference
        // satisfies and mutant breaks for some input. We assert that after
        // calling withdraw via the proxy, either the call reverted or
        // address(c).balance decreased by amount. The mutant can cause a
        // situation where the call does not revert but balance did not
        // decrease — that will violate this property.

        // Record balance before
        uint256 beforeBal = address(c).balance;

        bool ok;
        try proxy.callWithdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterBal = address(c).balance;

        // General rule: after attempting withdraw(amount) invoked by an owner-owned caller,
        // either the call reverts (ok == false) or the contract's balance decreased by amount.
        // The reference implementation (using transfer) enforces this for all inputs; the mutant
        // (using send with different semantics) can produce a successful call (ok == true) but
        // leave the contract balance unchanged (afterBal == beforeBal), violating the rule.
        assertTrue(!ok || (beforeBal - afterBal == amount));
    }
}

// Helper that will call c.withdraw from its context and then revert on receive
contract ReverterCaller {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    function callWithdraw(uint256 amount) public {
        // call withdraw so msg.sender in c is this contract
        c.withdraw(amount);
    }
    // revert when receiving funds to emulate a failing recipient
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}

